"""Japanese text/notes and a fixed preview viewport; original navigation/sync stay intact."""
import json,re
TRANSLATIONS={'讲述要点': '話す要点', '本页目的': 'この頁の目的', '本页演讲メモ': 'この頁の発表メモ', '同步状态': '同期状態', '已同步': '同期済み', '未连接': '未接続', '已连接': '接続済み', '观众窗口': '観客ウィンドウ', '观众': '観客', '控制台': '操作画面', '演讲标注层': '発表用注釈', '清除': '消去', '选择页面': 'ページを選ぶ', '返回预览': 'プレビューへ戻る', '戻る预览': 'プレビューへ戻る', '预览': 'プレビュー', '本页': 'この頁', '标题': 'タイトル', '已保存': '保存済み', '未保存': '未保存', '缩小': '小さくする', '放大': '大きくする', '字号': '文字サイズ', '已进行': '経過', '总时长': '全体時間', '计划': '予定', '未设置': '未設定', '设置': '設定', '检查': '確認', '宫格': 'ページ一覧', '首页': '最初の頁', '尾页': '最後の頁', '排练记录': 'リハーサル記録', '最近排练': '最近のリハーサル', '排练': 'リハーサル', '超时': '時間超過', '剩余': '残り', '已超出': '超過', '预计': '予定終了', '分钟': '分', '实际': '実際', '与': 'との', '相比': '比較', '没有记录到页面时间': 'ページ時間の記録はありません', '本次': '今回', '页面': 'ページ', '结束后': '終了後', '断开': '切断', '断线': '切断', '重连': '再接続', '关闭': '閉じる', '打开': '開く', '本地': 'ローカル', '清空': '消去', '计时': '計時', '分钟数': '分数', '保存成功': '保存しました', '快捷': 'クイック', '同歩': '同期'}
NOTES=[{'id': 'page-1', 'title': '週末の汐見港町', 'purpose': '商店会に2週末・4日の試行への合意を求める', 'talk': ['市場・食・工房・灯台を、一つの徒歩行程として提案します。', '汐見港町も予算も架空の設定で、営業案内や実施実績ではありません。', '参加店舗の合意後に、試行日と現地条件を確かめます。'], 'transition': 'まず、誰に何を体験してもらうかを絞ります。'}, {'id': 'page-2', 'title': '徒歩で半日を楽しむ来訪者へ。', 'purpose': '対象者と半日の体験をそろえる', 'talk': ['車を置いたあと徒歩で半日を過ごせる来訪者を想定します。', '個々の店を並べるだけでなく、次の店までの行き方を案内します。', 'すべての来訪者を一度に対象にする計画ではありません。'], 'transition': '体験を、時刻付きの一つの行程へ置きます。'}, {'id': 'page-3', 'title': '港から灯台へ、戻る。', 'purpose': '出発から帰着までの6停留所を確認する', 'talk': ['11時の案内所から15時の帰着までを仮に置いています。', '市場、食堂、工房、灯台を巡る順序を確認してください。', '4時間と約4kmは計画値で、実施前に歩いて時間と利用条件を確認します。'], 'transition': 'この行程を、来訪前と各店でどう案内するかを考えます。'}, {'id': 'page-4', 'title': '来る前と、店を出た後をつなぐ。', 'purpose': '共通の地図と次の行先をそろえる', 'talk': ['来訪前の案内と、各店を出るときの案内を一続きにします。', '全店舗で同じ地図と時刻案内を使う計画です。', '休日の営業時間を前日に確認し、案内と現地の不一致を避けます。'], 'transition': '続いて、試行を支える人数と費用を確認します。'}, {'id': 'page-5', 'title': '4日間で、運営を試す。', 'purpose': '人数・予算・例外時の対応を合意する', 'talk': ['2週末・4日、スタッフ2人という仮の運営条件です。', '案内物6万円、スタッフ16万円、記録・調整6万円で合計28万円です。', '雨天時は短縮し、混雑時は時間指定で分散する案を用意します。'], 'transition': '費用を使った後に何を見て判断するかを決めます。'}, {'id': 'page-6', 'title': '回った距離より、次につながったか。', 'purpose': '試行目標と測定範囲を分ける', 'talk': ['60人、全行程40%以上、カード回収70%以上は目標値です。', '匿名カードを各店で記録し、帰着時に回収する計画です。', 'この試行だけで、町全体の売上増加を断定しません。'], 'transition': '最後に、試行前に決めることを確認します。'}, {'id': 'page-7', 'title': 'まず、歩いて確かめる。', 'purpose': '合意・現地確認・日程決定へ進む', 'talk': ['参加店舗の合意を取り、時間と距離、休憩と雨天時の動線を現地確認します。', '確認後に試行日を決め、記録方法をスタッフでそろえます。', '試行の記録を見て、継続・変更・中止の条件を判断します。'], 'transition': '以上の準備と2週末の試行を、合意事項として確認します。'}]
def apply_locale_notes(doc):
 doc=doc.replace("grid-template-rows:minmax(0,1fr) clamp(132px,22vh,210px)","grid-template-rows:minmax(0,1fr) minmax(0,.85fr)").replace(".ppt-next-frame{opacity:.86}",".ppt-next-frame{opacity:1}")
 doc=doc.replace('frame.style.width=`${width}px`;frame.style.height=`${height}px`;', 'frame.style.width="1280px";frame.style.height="720px";frame.style.maxWidth="none";frame.style.maxHeight="none";frame.style.position="absolute";frame.style.left="50%";frame.style.top="50%";frame.style.transform=`translate(-50%,-50%) scale(${width/1280})`;frame.style.transformOrigin="center";')
 for old,new in {'已到最後の頁': '最後のページです', '演示終了': '発表終了', '演示已終了': '発表終了', '重新開始': '最初から再開', '重新確認': '再確認', '已到最后的页': '最後のページです', '演示结束': '発表終了', '重新开始': '最初から再開', '重新打开观众': '観客画面を再度開く', '重新開く観客画面': '観客画面を再度開く', '激光': 'レーザー', '圈选': '囲む', '【转场】':'【次の頁へ】', '建议': '目安', '第 ${': '${', ' 页': ' ページ', '自动翻页': '自動ページ送り'}.items():doc=doc.replace(old,new)
 for old,new in sorted(TRANSLATIONS.items(),key=lambda x:-len(x[0])):doc=doc.replace(old,new)
 doc=doc.replace('重新開く観客', '観客画面を再度開く').replace('第 ', '').replace(' 页', ' ページ')
 for old,new in {'自動ページ送り · 閉じる':'自動ページ送り · OFF', '自動ページ送り · 等待时长':'自動ページ送り · ON／間隔未設定', '自動ページ送り · 已終了':'自動ページ送り · ON／終了', '自動ページ送り · ${':'自動ページ送り · ON／${', '开启 / 閉じる自動ページ送り':'自動ページ送り ON / OFF', '退出':'終了', '激光笔':'レーザーポインター', '圈选':'囲む'}.items():doc=doc.replace(old,new)
 doc=doc.replace("autoPlay ? '開く' : '閉じる'", "autoPlay ? 'ON' : 'OFF'").replace("autoplay ? '開く' : '閉じる'", "autoplay ? 'ON' : 'OFF'")
 return re.sub(r'const SPEAKER_NOTES\s*=\s*\[.*?\]\s*;',lambda m:'const SPEAKER_NOTES = '+json.dumps(NOTES,ensure_ascii=False)+';',doc,count=1,flags=re.S)
